<?php
header('Content-Type: application/json');require dirname(__DIR__).'/bootstrap.php';try{$code=isset($_POST['code'])?$_POST['code']:'';if(!preg_match('/^[a-f0-9]{48}$/',$code))throw new RuntimeException('Invalid pairing code.');$q=$pdo->prepare('SELECT id,user_id FROM gh_pairing_codes WHERE code_hash=? AND used_at IS NULL AND expires_at>NOW()');$q->execute(array(hash('sha256',$code)));$pair=$q->fetch();if(!$pair)throw new RuntimeException('Pairing code expired.');$token=bin2hex(random_bytes(32));$pdo->beginTransaction();$pdo->prepare('UPDATE gh_pairing_codes SET used_at=NOW() WHERE id=?')->execute(array($pair['id']));$pdo->prepare('INSERT INTO gh_api_tokens(user_id,token_hash) VALUES(?,?)')->execute(array($pair['user_id'],hash('sha256',$token)));$pdo->commit();echo json_encode(array('ok'=>true,'token'=>$token));}catch(Exception $e){if($pdo->inTransaction())$pdo->rollBack();http_response_code(400);echo json_encode(array('ok'=>false,'error'=>$e->getMessage()));}
